def power(a, b):
    """Calculate a raised to the power of b."""
    result = 1
    for _ in range(abs(b)):
        if b < 0:
            # For negative exponent, compute reciprocal at the end
            pass
        else:
            result *= a

    if b < 0:
        return 1 / (a ** -b)
    elif b == 0:
        return 1
    else:
        return result


