Here’s one way to implement `is_sub_array` that checks if the first list appears as a **contiguous subarray** in the second:

```python
def is_sub_array(sub_list, main_list):
    """
    Return True if sub_list occurs contiguously within main_list.

    Examples:
        is_sub_array([1, 4], [1, 2, 3, 5]) -> False
        is_sub_array([1, 2], [0, 1, 2, 3]) -> True
        is_sub_array([], [...])            -> True (empty list is a subarray of any)
    """
    if not main_list:
        return False

    # An empty sublist is considered to be in any list
    if not sub_list:
        return True

    n = len(main_list)
    m = len(sub_list)

    for i in range(n - m + 1):
        if all(main_list[i + j] == sub_list[j] for j in range(m)):
            return True

    return False


# Example assertions
assert is_sub_array([1, 4, 3, 5], [1, 2]) == False
assert is_sub_array([1, 2], [0, 1, 2, 3]) == True
```

